(1, '일반 채팅방', '관리자1', 'admin', 1, '누구나 참여 가능한 일반적인 채팅방입니다', 100, 0, 0, NULL, '2024-01-01 00:00:00', '2024-01-15 00:00:00'),
(2, '개발자 모임', '개발팀장', 'developer123', 1, '개발 관련 정보와 질문을 공유하는 채팅방', 50, 0, 0, NULL, '2024-01-05 00:00:00', '2024-01-15 00:00:00'),
(3, '게임 토크', '게임마스터', 'gameplayer', 1, '게임에 대한 이야기를 나누는 공간', 80, 0, 0, NULL, '2024-01-10 00:00:00', '2024-01-15 00:00:00'),
(4, 'VIP 라운지', '관리자1', 'admin', 1, '특별 회원을 위한 프리미엄 채팅방', 20, 0, 1, '0000', '2024-01-12 00:00:00', '2024-01-15 00:00:00');
INSERT IGNORE INTO post (id, userId, title, content, createdAt, updatedAt, deletedAt) VALUES
(1, 2, '더 이상 혼자 고민하지 마세요! 2025년 개인 개발의 파트너 도구 모음', '## 더 이상 혼자 고민하지 마세요! 2025년 개인 개발의 파트너 도구 모음\n\n![포스트 썸네일](https://picsum.photos/seed/1/600/360)\n\n> **서론**\n>\n> 최근 개인 개발 프로젝트를 진행하면서 깊이 느낀 점이 있는데, "적절한 도구 선택"이 정말 중요하다는 것입니다. 특히 AI 시대인 지금, 도구 하나의 선택으로 개발 속도가 2배, 3배로 달라질 수 있습니다. 저 자신도 작년까지는 "코드만 작성할 수 있으면 OK"라고 생각했지만, 어느 날 선배 엔지니어에게 "이런 방식으로는 시간이 아깝다"라는 말을 듣고 눈을 떴습니다. 그래서 이번에는 제가 실제로 사용해보고 "이것은 정말 대단하다!"라고 느낀 2025년 버전의 개인 개발 도구를 엄선해서 소개해 드리겠습니다. 모두 실제 개발 현장에서 사용할 수 있는 것들이니 참고해 보세요.\n\n---\n\n### 1. 코드 작성\n\n- **VS Code**\n- **JetBrains IDEs**\n\n```javascript\n// 예시 코드 블록\nfunction sum(a, b) {\n  return a + b;\n}\n\nconsole.log(sum(1, 2)); // 3\n```\n\n---\n\n### 2. 버전 관리\n\n- **Git**\n- **GitHub**\n- **GitLab**\n\n---\n\n### 3. 프로젝트 관리\n\n- **Notion**\n- **Trello**\n\n---\n\n### 4. 배포\n\n- **Vercel**\n- **Netlify**\n\n---\n\n> **결론**\n>\n> 이 외에도 많은 훌륭한 도구들이 있지만, 저는 위 도구들을 통해 개인 개발 효율을 크게 높일 수 있었습니다. 이 글이 여러분의 개발 여정에도 도움이 되기를 바랍니다. 궁금한 점이 있다면 댓글로 남겨주세요!', '2025-08-01 12:00:00', '2025-08-01 12:00:00', NULL),
(2, -1, '[ERROR CASE] 에러페이지 테스트', '클릭 시 에러가 발생합니다.', '2026-02-20 09:30:00', '2026-02-20 09:30:00', NULL),
(3, 2, 'React 성능 최적화: 렌더링 병목 찾는 5가지 방법', 'React 앱의 성능 문제를 해결하려면 우선 병목을 정확히 측정해야 합니다. 프로파일링, 메모이제이션, 레이지 로딩, 리스트 가상화, 불필요한 상태 끌어올리기 등 실무에서 자주 쓰는 패턴을 실제 사례와 함께 정리했습니다.\n\n![React 성능 최적화 이미지](https://picsum.photos/seed/3/600/360)', '2025-06-15 15:45:00', '2025-06-16 08:00:00', NULL),
(4, 0, '작은 팀을 위한 깔끔한 코드 리뷰 규칙', '코드 리뷰는 품질을 높이는 가장 강력한 도구입니다. 다만 리뷰 문화가 없거나 기준이 없으면 사소한 논쟁이 늘어나 생산성이 떨어집니다. 이 글에서는 작은 팀에서 적용하기 좋은 7가지 규칙을 제안합니다: 목적 정의, PR 크기 제한, 자동화 도구 활용, 긍정적 피드백 우선 등.\n\n![코드 리뷰 이미지](https://picsum.photos/seed/4/600/360)', '2025-05-10 11:00:00', '2025-05-10 11:00:00', NULL),
(5, 3, '개발자를 위한 생산성 도구: 네이티브 앱 vs 웹 앱', '생산성 도구를 선택할 때 데스크탑 네이티브 앱과 웹 앱 사이에서 고민하는 경우가 많습니다. 이 글에서는 각각의 장단점, 오프라인 지원, 동기화 전략, 배포 편의성 등을 비교하고, 개인 개발 환경에 맞는 추천 설정을 제시합니다.\n\n![생산성 도구 이미지](https://picsum.photos/seed/5/600/360)', '2025-04-01 08:00:00', '2025-04-01 08:00:00', NULL),
(6, 2, '모던 자바스크립트 모듈 시스템 정리', 'ESM과 CommonJS의 차이, 번들링 이후의 모듈 로딩 전략, dynamic import와 트리 쉐이킹을 활용한 번들 최적화 방법을 정리합니다.\n\n![자바스크립트 모듈 이미지](https://picsum.photos/seed/6/600/360)', '2025-03-22 10:15:00', '2025-03-22 10:15:00', NULL),
(7, 1, 'CSS-in-JS vs 전통적 CSS: 언제 어떤걸 선택할까', '스타일링 전략은 유지보수성과 성능에 큰 영향을 줍니다. 컴포넌트 기반 개발에서의 장단점과 실무 적용 팁을 사례와 함께 소개합니다.\n\n![CSS-in-JS 이미지](https://picsum.photos/seed/7/600/360)', '2025-02-14 14:00:00', '2025-02-14 14:00:00', NULL),
(8, 4, '간단한 서버리스 API 설계 가이드', '서버리스 환경에서 API를 설계할 때 주의할 점: 인증, 비용 최적화, cold start 완화, 로깅과 모니터링을 중심으로 실무 팁을 정리합니다.\n\n![서버리스 API 이미지](https://picsum.photos/seed/8/600/360)', '2025-01-30 09:00:00', '2025-01-30 09:00:00', NULL),
(9, 2, '작업흐름 자동화: GitHub Actions로 시작하기', 'CI/CD를 처음 도입하는 팀을 위해 GitHub Actions 기반의 간단한 워크플로 작성법, 보안, 그리고 배포 전략을 단계별로 안내합니다.\n\n![GitHub Actions 이미지](https://picsum.photos/seed/9/600/360)', '2025-01-10 16:20:00', '2025-01-10 16:20:00', NULL),
(10, 2, 'TypeScript로 안전하게 대규모 리팩터링하기', 'TypeScript의 타입 시스템을 활용해 리팩터링 범위를 안전하게 넓히는 방법, 점진적 마이그레이션 전략과 유용한 타입 유틸리티를 설명합니다.\n\n![TypeScript 리팩터링 이미지](https://picsum.photos/seed/10/600/360)', '2024-12-05 13:00:00', '2024-12-05 13:00:00', NULL),
(11, 3, '서비스 운영에서 학습한 로깅과 트러블슈팅 요령', '인시던트 대응 경험을 바탕으로 로그 수집, 지표 설계, 빠른 원인 파악을 위한 체크리스트와 실무 예시를 공유합니다.\n\n![로깅과 트러블슈팅 이미지](https://picsum.photos/seed/11/600/360)', '2024-11-18 10:00:00', '2024-11-18 10:00:00', NULL),
(12, 1, '웹 접근성(Accessibility) 기본 체크리스트', '접근성은 모두를 위한 기능입니다. 마크업/ARIA/키보드 네비게이션/컬러 대비 등의 기본 체크리스트와 자동화 툴 사용법을 정리합니다.\n\n![웹 접근성 이미지](https://picsum.photos/seed/12/600/360)', '2024-10-30 09:45:00', '2024-10-30 09:45:00', NULL),
(13, 4, '경량화된 이미지 최적화 전략', '이미지 형식 선택(AVIF/WebP/PNG), 레이지 로딩, CDN 활용, 빌드 타임 변환에 대한 실전 팁을 설명합니다.\n\n![이미지 최적화 이미지](https://picsum.photos/seed/13/600/360)', '2024-09-12 12:00:00', '2024-09-12 12:00:00', NULL),
(14, 0, '소규모 서비스에서의 데이터베이스 선택 가이드', '관계형 DB와 NoSQL의 장단점을 소규모 서비스 관점에서 정리하고, 마이그레이션 고려사항과 운영 팁을 제공합니다.\n\n![데이터베이스 선택 이미지](https://picsum.photos/seed/14/600/360)', '2024-08-05 11:30:00', '2024-08-05 11:30:00', NULL),
(15, 2, '효율적인 에러 핸들링 패턴 모음', '프론트엔드와 백엔드 각각에서 사용할 수 있는 에러 핸들링 패턴을 사례별로 정리하고, 공통적으로 적용 가능한 모범 사례를 제안합니다.\n\n![에러 핸들링 이미지](https://picsum.photos/seed/15/600/360)', '2024-07-01 07:00:00', '2024-07-01 07:00:00', NULL),
(16, 4, '모바일 퍼포먼스 튜닝: 렌더링 최적화 체크리스트', '모바일 환경에서 렌더링 성능을 개선하기 위한 실전 체크리스트와 사례를 정리했습니다. 레이아웃 스래싱, 레이지로딩, 이미지 최적화 중심.\n\n![모바일 퍼포먼스 이미지](https://picsum.photos/seed/16/600/360)', '2024-06-20 10:00:00', '2024-06-20 10:00:00', NULL),
(17, 1, 'Docker로 로컬 개발환경 통일하기', '개발팀이 동일한 환경에서 작업하도록 Docker를 도입할 때 고려할 설정, 권장 베이스 이미지, 그리고 도구들을 정리했습니다.\n\n![Docker 이미지](https://picsum.photos/seed/17/600/360)', '2024-06-01 09:00:00', '2024-06-01 09:00:00', NULL),
(18, 3, '작업 우선순위 정하기: RICE와 MoSCoW 비교', '프로덕트 개발에서 기능 우선순위를 정할 때 사용하는 프레임워크를 비교하고, 작은 팀에서 적용하는 방법을 사례와 함께 설명합니다.\n\n![작업 우선순위 이미지](https://picsum.photos/seed/18/600/360)', '2024-05-18 13:30:00', '2024-05-18 13:30:00', NULL),
(19, 0, '간단한 상태 관리 도구 비교: Recoil vs Zustand vs Redux', '프로젝트 규모와 팀에 맞는 상태관리 선택 기준과 각 라이브러리의 장단점을 실무 예제와 함께 설명합니다.\n\n![상태 관리 이미지](https://picsum.photos/seed/19/600/360)', '2024-04-25 11:10:00', '2024-04-25 11:10:00', NULL),
(20, 2, 'GraphQL을 도입할 때 고려할 7가지', 'GraphQL 스키마 설계, 성능, 캐싱, 보안 등 도입 전 체크리스트를 정리했습니다. REST와의 혼용 전략도 다룹니다.\n\n![GraphQL 이미지](https://picsum.photos/seed/20/600/360)', '2024-04-10 08:45:00', '2024-04-10 08:45:00', NULL),
(21, 4, '로컬 개발에서의 비밀 관리: .env와 시크릿 스토어', '개발 환경에서 비밀값을 안전하게 관리하는 방법과 팀 공유 시 주의할 점, 추천 툴을 소개합니다.\n\n![비밀 관리 이미지](https://picsum.photos/seed/21/600/360)', '2024-03-05 12:00:00', '2024-03-05 12:00:00', NULL),
(22, 1, '프로그래밍 학습 로드맵: 6개월 계획 예시', '초보자가 6개월 동안 실무 수준으로 성장하기 위한 학습 로드맵과 주 단위 목표 설정 방법을 제안합니다.\n\n![학습 로드맵 이미지](https://picsum.photos/seed/22/600/360)', '2024-02-20 09:00:00', '2024-02-20 09:00:00', NULL),
(23, 3, '오픈 소스 기여를 시작하는 방법', '처음 오픈 소스에 기여하는 사람들을 위해 이슈 찾기, PR 작성 규칙, 유지보수자와의 커뮤니케이션 팁을 정리했습니다.\n\n![오픈 소스 기여 이미지](https://picsum.photos/seed/23/600/360)', '2024-01-15 10:30:00', '2024-01-15 10:30:00', NULL),
(24, 0, 'SWR과 React-Query 성능 비교', '데이터 페칭 라이브러리를 선택할 때 고려할 점과, SWR과 React-Query의 내부 전략 차이 및 성능 특성을 비교합니다.\n\n![SWR과 React-Query 이미지](https://picsum.photos/seed/24/600/360)', '2023-12-10 14:00:00', '2023-12-10 14:00:00', NULL),
(25, 2, '프로덕트 디자인 기초: 사용자 여정 맵 작성법', '서비스 기획 시 사용자 여정 지도를 작성하는 방법과 인터뷰 기반 개선 포인트 찾기 방법을 설명합니다.\n\n![사용자 여정 맵 이미지](https://picsum.photos/seed/25/600/360)', '2023-11-01 09:00:00', '2023-11-01 09:00:00', NULL),
(26, 4, '간단한 성능 테스트: Lighthouse 활용 가이드', '웹 성능을 측정하기 위해 Lighthouse를 사용하는 방법과 점수 해석, 개선 우선순위를 정하는 방법을 설명합니다.\n\n![Lighthouse 성능 테스트 이미지](https://picsum.photos/seed/26/600/360)', '2023-10-20 08:00:00', '2023-10-20 08:00:00', NULL),
(27, 1, '작은 팀을 위한 회고 문화 만들기', '정기적인 회고를 통해 팀의 개선점을 찾는 방법과 회고에서 피해야 할 실수들을 정리합니다.\n\n![회고 문화 이미지](https://picsum.photos/seed/27/600/360)', '2023-09-15 15:00:00', '2023-09-15 15:00:00', NULL),
(28, 3, '프로덕션에서의 모니터링: 메트릭과 알림 설정', '핵심 메트릭을 정의하고 알림 정책을 설계하는 방법, 그리고 경보의 소음(노이즈) 줄이는 전략을 공유합니다.\n\n![모니터링 이미지](https://picsum.photos/seed/28/600/360)', '2023-08-01 07:30:00', '2023-08-01 07:30:00', NULL),
(29, 0, '빠른 프로토타입을 위한 디자인 툴 비교', 'Figma, Sketch, Adobe XD 등 디자인 툴의 장단점과 빠른 프로토타입 제작 팁을 정리했습니다.\n\n![디자인 툴 비교 이미지](https://picsum.photos/seed/29/600/360)', '2023-07-10 12:00:00', '2023-07-10 12:00:00', NULL),
(30, 2, '대규모 트래픽 대응을 위한 캐시 전략', 'CDN, 애플리케이션 레벨 캐시, DB 캐시 전략을 조합해 대규모 트래픽을 효율적으로 처리하는 방법을 설명합니다.\n\n![캐시 전략 이미지](https://picsum.photos/seed/30/600/360)', '2023-06-01 06:00:00', '2023-06-01 06:00:00', NULL),
(31, 3, 'Vue 3 Composition API 완벽 가이드', 'Vue 2의 Options API와 비교하여 Composition API가 가지는 장점과 재사용성, 그리고 `setup` 함수의 올바른 사용법을 다룹니다.\n\n![Vue 3 이미지](https://picsum.photos/seed/31/600/360)', '2023-05-20 10:00:00', '2023-05-20 10:00:00', NULL),
(32, 1, 'AWS Lambda 비용 최적화 전략', '서버리스 아키텍처에서 발생할 수 있는 콜드 스타트 문제와 메모리 할당량 조절을 통한 비용 절감 노하우를 공유합니다.\n\n![AWS Lambda 이미지](https://picsum.photos/seed/32/600/360)', '2023-05-15 14:30:00', '2023-05-15 14:30:00', NULL),
(33, 4, '주니어 개발자를 위한 이력서 작성법', '기술 스택 나열이 아닌, 문제 해결 능력을 보여주는 이력서 작성 팁과 포트폴리오 구성 방법을 정리했습니다.\n\n![이력서 작성 이미지](https://picsum.photos/seed/33/600/360)', '2023-05-10 09:00:00', '2023-05-10 09:00:00', NULL),
(34, 2, 'Tailwind CSS: 유틸리티 퍼스트의 장단점', '기존 CSS 방식과 Tailwind CSS의 생산성 차이를 비교하고, 팀 프로젝트 도입 시 고려해야 할 디자인 시스템 설정법을 알아봅니다.\n\n![Tailwind CSS 이미지](https://picsum.photos/seed/34/600/360)', '2023-05-05 11:15:00', '2023-05-05 11:15:00', NULL),
(35, 0, 'NoSQL vs RDBMS: 언제 무엇을 써야 할까?', '데이터의 무결성이 중요한 금융 서비스와 유연한 스키마가 필요한 로그 시스템 등 상황별 DB 선택 기준을 제시합니다.\n\n![DB 비교 이미지](https://picsum.photos/seed/35/600/360)', '2023-04-30 16:20:00', '2023-04-30 16:20:00', NULL),
(36, 1, 'Next.js 13+ App Router 마이그레이션 후기', 'Pages Router에서 App Router로 이전하면서 겪은 시행착오와 서버 컴포넌트(RSC)의 실제 효용성을 분석합니다.\n\n![Next.js 이미지](https://picsum.photos/seed/36/600/360)', '2023-04-25 08:45:00', '2023-04-25 08:45:00', NULL),
(37, 3, 'Flutter로 크로스 플랫폼 앱 시작하기', '단일 코드베이스로 iOS와 Android를 동시에 개발하는 Flutter의 기본 위젯 구조와 상태 관리 패턴(Provider, Riverpod)을 소개합니다.\n\n![Flutter 이미지](https://picsum.photos/seed/37/600/360)', '2023-04-20 13:00:00', '2023-04-20 13:00:00', NULL),
(38, 2, '웹 보안 기초: XSS와 CSRF 방어하기', '프론트엔드 개발자가 반드시 알아야 할 웹 공격 유형과 이를 방어하기 위한 쿠키 설정, Content Security Policy(CSP) 적용법을 다룹니다.\n\n![웹 보안 이미지](https://picsum.photos/seed/38/600/360)', '2023-04-15 10:30:00', '2023-04-15 10:30:00', NULL),
(39, 4, '클린 아키텍처: 프론트엔드에 적용하기', '비즈니스 로직과 UI를 분리하여 유지보수성을 높이는 클린 아키텍처의 개념을 React 프로젝트 예시와 함께 설명합니다.\n\n![클린 아키텍처 이미지](https://picsum.photos/seed/39/600/360)', '2023-04-10 15:50:00', '2023-04-10 15:50:00', NULL),
(40, 0, 'Python FastAPI로 비동기 서버 구축하기', 'Flask/Django와 비교한 FastAPI의 성능적 이점과 Pydantic을 이용한 강력한 데이터 검증 기능을 소개합니다.\n\n![FastAPI 이미지](https://picsum.photos/seed/40/600/360)', '2023-04-05 09:20:00', '2023-04-05 09:20:00', NULL),
(41, 2, '개발자의 번아웃 관리와 휴식', '열정적으로 일하는 것만큼 중요한 효율적인 휴식 방법과 번아웃 증후군을 조기에 감지하고 대처하는 개인적인 경험담입니다.\n\n![번아웃 관리 이미지](https://picsum.photos/seed/41/600/360)', '2023-03-31 19:00:00', '2023-03-31 19:00:00', NULL),
(42, 1, 'Kubernetes 입문: Pod와 Service 이해하기', '컨테이너 오케스트레이션의 표준인 K8s의 핵심 개념인 Pod, Deployment, Service의 관계를 쉽게 풀어서 설명합니다.\n\n![Kubernetes 이미지](https://picsum.photos/seed/42/600/360)', '2023-03-25 14:10:00', '2023-03-25 14:10:00', NULL),
(43, 3, 'Jest와 React Testing Library 실전 예제', '단위 테스트(Unit Test) 작성의 중요성과 버튼 클릭, API 호출 모킹(Mocking) 등 실무에서 자주 쓰이는 테스트 케이스를 공유합니다.\n\n![테스트 코드 이미지](https://picsum.photos/seed/43/600/360)', '2023-03-20 11:00:00', '2023-03-20 11:00:00', NULL),
(44, 4, 'OAuth 2.0 소셜 로그인 구현 원리', '카카오, 구글 로그인을 구현하며 겪는 인증 토큰 발급 과정과 Refresh Token을 이용한 세션 유지 전략을 정리했습니다.\n\n![OAuth 이미지](https://picsum.photos/seed/44/600/360)', '2023-03-15 16:40:00', '2023-03-15 16:40:00', NULL),
(45, 0, 'Rust 언어: 자바스크립트 개발자의 시선', '메모리 안전성과 성능을 모두 잡은 Rust를 배우며 느낀 점과, 웹 어셈블리(Wasm) 생태계에서의 가능성을 탐구합니다.\n\n![Rust 이미지](https://picsum.photos/seed/45/600/360)', '2023-03-10 08:30:00', '2023-03-10 08:30:00', NULL),
(46, 2, '모노레포(Monorepo) 도입 가이드 with Turborepo', '여러 프로젝트를 하나의 저장소에서 관리할 때의 장단점과 Turborepo를 활용한 빌드 캐싱 최적화 방법을 소개합니다.\n\n![모노레포 이미지](https://picsum.photos/seed/46/600/360)', '2023-03-05 12:20:00', '2023-03-05 12:20:00', NULL),
(47, 1, 'Storybook을 활용한 UI 컴포넌트 문서화', '디자이너와 개발자의 협업 효율을 높이는 Storybook 설정법과 인터랙티브한 컴포넌트 가이드라인 작성 팁입니다.\n\n![Storybook 이미지](https://picsum.photos/seed/47/600/360)', '2023-02-28 10:50:00', '2023-02-28 10:50:00', NULL),
(48, 3, 'Redis를 활용한 캐싱 전략 심화', 'Look-aside, Write-back 등 다양한 캐싱 패턴을 알아보고, 실제 서비스에서 API 응답 속도를 10배 개선한 사례를 공유합니다.\n\n![Redis 이미지](https://picsum.photos/seed/48/600/360)', '2023-02-22 15:15:00', '2023-02-22 15:15:00', NULL),
(49, 4, '개발 생산성을 높이는 크롬 익스텐션 5선', 'JSON Formatter, React DevTools 등 웹 개발자라면 반드시 설치해야 할 필수 크롬 확장 프로그램들을 추천합니다.\n\n![크롬 익스텐션 이미지](https://picsum.photos/seed/49/600/360)', '2023-02-18 09:40:00', '2023-02-18 09:40:00', NULL),
(50, 0, 'Linux 기본 명령어 마스터하기', '서버 관리의 기본이 되는 리눅스 명령어(grep, awk, sed 등)의 활용법과 쉘 스크립트 작성 기초를 다룹니다.\n\n![Linux 이미지](https://picsum.photos/seed/50/600/360)', '2023-02-12 13:00:00', '2023-02-12 13:00:00', NULL),
(51, 2, 'WebSocket을 이용한 실시간 채팅 구현', 'HTTP와 WebSocket의 차이를 이해하고, Socket.io를 사용하여 간단한 실시간 채팅방을 만드는 과정을 보여줍니다.\n\n![WebSocket 이미지](https://picsum.photos/seed/51/600/360)', '2023-02-08 17:30:00', '2023-02-08 17:30:00', NULL),
(52, 1, 'JIRA와 Confluence를 이용한 애자일 협업', '스프린트 계획, 백로그 관리, 문서화 등 애자일 프로세스를 지원하는 아틀라시안 도구들의 효율적인 사용법입니다.\n\n![협업 도구 이미지](https://picsum.photos/seed/52/600/360)', '2023-02-03 11:20:00', '2023-02-03 11:20:00', NULL),
(53, 3, 'SEO(검색 엔진 최적화) 핵심 체크리스트', '메타 태그 설정, 시맨틱 마크업, 사이트맵 제출 등 내 웹사이트를 구글 상단에 노출시키기 위한 기술적 SEO 방법을 정리합니다.\n\n![SEO 이미지](https://picsum.photos/seed/53/600/360)', '2023-01-29 08:50:00', '2023-01-29 08:50:00', NULL),
(54, 4, 'Terraform으로 인프라를 코드로 관리하기(IaC)', '클라우드 인프라를 수동으로 생성하지 않고 코드로 관리(IaC)할 때의 장점과 Terraform 기본 문법을 소개합니다.\n\n![Terraform 이미지](https://picsum.photos/seed/54/600/360)', '2023-01-24 14:00:00', '2023-01-24 14:00:00', NULL),
(55, 0, '알고리즘 코딩 테스트 준비 전략', '효율적인 문제 풀이 접근법, 자주 나오는 자료구조(해시, 스택/큐, 힙) 정리 및 실전 모의고사 활용 팁입니다.\n\n![코딩 테스트 이미지](https://picsum.photos/seed/55/600/360)', '2023-01-19 10:10:00', '2023-01-19 10:10:00', NULL),
(56, 2, 'Svelte: 가상 돔 없는 프레임워크의 매력', 'React/Vue와 달리 빌드 타임에 코드를 최적화하여 런타임 오버헤드를 줄이는 Svelte의 동작 원리와 간단한 예제입니다.\n\n![Svelte 이미지](https://picsum.photos/seed/56/600/360)', '2023-01-14 16:50:00', '2023-01-14 16:50:00', NULL),
(57, 1, 'MSA(마이크로서비스) 전환 시 고려사항', '모놀리식 아키텍처에서 MSA로 전환할 때 발생하는 트랜잭션 관리, 배포 복잡도 등 현실적인 문제점과 해결 방안입니다.\n\n![MSA 이미지](https://picsum.photos/seed/57/600/360)', '2023-01-09 09:30:00', '2023-01-09 09:30:00', NULL),
(58, 3, 'Git Rebase vs Merge: 차이점 완벽 정리', '커밋 히스토리를 깔끔하게 관리하기 위한 Rebase 전략과, 협업 시 충돌을 최소화하는 Merge 전략을 비교 설명합니다.\n\n![Git 전략 이미지](https://picsum.photos/seed/58/600/360)', '2023-01-04 13:40:00', '2023-01-04 13:40:00', NULL),
(59, 4, '디자인 패턴: 싱글톤과 팩토리 패턴', '소프트웨어 설계에서 자주 사용되는 디자인 패턴의 개념을 이해하고, 실제 코드에서 어떻게 적용되는지 예시를 듭니다.\n\n![디자인 패턴 이미지](https://picsum.photos/seed/59/600/360)', '2022-12-30 11:00:00', '2022-12-30 11:00:00', NULL),
(60, 0, 'Elasticsearch를 이용한 검색 엔진 구축', 'RDBMS의 `LIKE` 검색 한계를 극복하고, 역색인 구조를 활용해 고성능 전문 검색(Full-text Search)을 구현하는 방법입니다.\n\n![Elasticsearch 이미지](https://picsum.photos/seed/60/600/360)', '2022-12-25 08:00:00', '2022-12-25 08:00:00', NULL),
(61, 2, 'PWA(Progressive Web App) 도입기', '웹 기술로 네이티브 앱과 유사한 사용자 경험을 제공하는 PWA의 핵심 기술인 서비스 워커와 매니페스트 설정법입니다.\n\n![PWA 이미지](https://picsum.photos/seed/61/600/360)', '2022-12-20 15:20:00', '2022-12-20 15:20:00', NULL),
(62, 1, 'HTTP/3와 QUIC 프로토콜의 미래', 'TCP 대신 UDP를 기반으로 하여 웹 통신 속도와 보안을 혁신적으로 개선한 HTTP/3의 특징과 도입 현황을 알아봅니다.\n\n![HTTP/3 이미지](https://picsum.photos/seed/62/600/360)', '2022-12-15 10:45:00', '2022-12-15 10:45:00', NULL),
(63, 3, '개발자 네트워킹과 커뮤니티 활동', '오프라인 컨퍼런스, 온라인 커뮤니티 활동이 커리어 성장에 미치는 영향과 효과적인 네트워킹 팁을 공유합니다.\n\n![네트워킹 이미지](https://picsum.photos/seed/63/600/360)', '2022-12-10 14:00:00', '2022-12-10 14:00:00', NULL),
(64, 4, 'SQL 튜닝: 인덱스의 원리와 활용', '데이터베이스 성능 최적화의 핵심인 인덱스(Index)의 작동 원리(B-Tree)와 올바른 인덱스 설계 방법을 설명합니다.\n\n![SQL 튜닝 이미지](https://picsum.photos/seed/64/600/360)', '2022-12-05 09:10:00', '2022-12-05 09:10:00', NULL),
(65, 0, 'Node.js 이벤트 루프 심층 분석', '싱글 스레드 기반인 Node.js가 어떻게 비동기 작업을 처리하는지, 이벤트 루프의 각 단계(Phase)를 그림으로 파헤칩니다.\n\n![이벤트 루프 이미지](https://picsum.photos/seed/65/600/360)', '2022-11-30 17:00:00', '2022-11-30 17:00:00', NULL),
(66, 2, '피그마(Figma) 오토 레이아웃 마스터하기', '개발자와의 협업을 위해 디자이너가 알아야 할 오토 레이아웃 기능과 반응형 디자인 설계 노하우를 정리합니다.\n\n![피그마 이미지](https://picsum.photos/seed/66/600/360)', '2022-11-25 12:30:00', '2022-11-25 12:30:00', NULL),
(67, 1, 'Go 언어(Golang)의 동시성 프로그래밍', '고루틴(Goroutine)과 채널(Channel)을 이용해 복잡한 동시성 문제를 쉽고 효율적으로 해결하는 Go 언어의 특징입니다.\n\n![Golang 이미지](https://picsum.photos/seed/67/600/360)', '2022-11-20 08:20:00', '2022-11-20 08:20:00', NULL),
(68, 3, 'CI/CD 파이프라인 구축 실패 사례', '자동 배포 환경을 구축하면서 겪었던 실패 경험과, 안정적인 CI/CD 파이프라인을 만들기 위한 체크리스트입니다.\n\n![CI/CD 이미지](https://picsum.photos/seed/68/600/360)', '2022-11-15 13:50:00', '2022-11-15 13:50:00', NULL),
(69, 4, 'API 문서화 도구 비교: Swagger vs Postman', 'REST API 명세를 관리하고 공유하기 위한 두 도구의 장단점을 비교하고, 팀의 상황에 맞는 도구 선택 가이드를 제공합니다.\n\n![API 문서화 이미지](https://picsum.photos/seed/69/600/360)', '2022-11-10 10:15:00', '2022-11-10 10:15:00', NULL),
(70, 0, '주니어 PM을 위한 요구사항 정의서 작성법', '개발자와 디자이너가 명확하게 이해할 수 있는 요구사항 정의서(PRD) 작성 요령과 커뮤니케이션 팁을 담았습니다.\n\n![PM 가이드 이미지](https://picsum.photos/seed/70/600/360)', '2022-11-05 16:00:00', '2022-11-05 16:00:00', NULL),
(71, 2, 'Three.js로 3D 웹사이트 만들기 기초', 'WebGL을 쉽게 다룰 수 있게 해주는 Three.js 라이브러리를 사용하여 웹 브라우저에 3D 큐브를 띄우는 튜토리얼입니다.\n\n![Three.js 이미지](https://picsum.photos/seed/71/600/360)', '2022-10-31 09:00:00', '2022-10-31 09:00:00', NULL),
(72, 1, 'Nginx vs Apache: 웹 서버 비교', '대표적인 웹 서버 소프트웨어인 Nginx와 Apache의 아키텍처 차이(이벤트 구동 vs 프로세스 구동)와 성능 비교입니다.\n\n![웹 서버 이미지](https://picsum.photos/seed/72/600/360)', '2022-10-26 14:40:00', '2022-10-26 14:40:00', NULL),
(73, 3, '오픈소스 라이선스 완벽 정리', 'MIT, Apache 2.0, GPL 등 헷갈리는 오픈소스 라이선스의 차이점과 상용 프로젝트 사용 시 주의사항을 알아봅니다.\n\n![라이선스 이미지](https://picsum.photos/seed/73/600/360)', '2022-10-21 11:10:00', '2022-10-21 11:10:00', NULL),
(74, 4, 'Slack 봇 만들기: 업무 자동화의 시작', '슬랙 API를 활용하여 매일 아침 팀의 지표를 자동으로 리포팅해주는 간단한 챗봇 개발 가이드입니다.\n\n![슬랙 봇 이미지](https://picsum.photos/seed/74/600/360)', '2022-10-16 08:30:00', '2022-10-16 08:30:00', NULL),
(75, 0, '프리랜서 개발자의 세금 관리 기초', '프리랜서로 전향하려는 개발자를 위해 종합소득세 신고, 사업자 등록 등 필수적인 세무 지식을 정리했습니다.\n\n![세금 관리 이미지](https://picsum.photos/seed/75/600/360)', '2022-10-11 15:55:00', '2022-10-11 15:55:00', NULL),
(76, 2, 'GraphQL 에러 핸들링 베스트 프랙티스', '항상 200 OK를 반환하는 GraphQL 특성상 에러를 어떻게 처리하고 클라이언트에 전달해야 하는지 모범 사례를 소개합니다.\n\n![GraphQL 에러 이미지](https://picsum.photos/seed/76/600/360)', '2022-10-06 10:20:00', '2022-10-06 10:20:00', NULL),
(77, 1, '파이썬 데이터 분석 라이브러리: Pandas vs Polars', '사실상 표준인 Pandas와 고성능 처리를 내세운 Polars의 속도 비교 및 대용량 데이터 처리 시 선택 가이드입니다.\n\n![데이터 분석 이미지](https://picsum.photos/seed/77/600/360)', '2022-10-01 13:15:00', '2022-10-01 13:15:00', NULL),
(78, 3, '개발 용어 정리: TDD, DDD, BDD', '테스트 주도 개발, 도메인 주도 설계, 행동 주도 개발 등 약어로 쓰이는 개발 방법론들의 핵심 개념을 쉽게 풀어봅니다.\n\n![개발 방법론 이미지](https://picsum.photos/seed/78/600/360)', '2022-09-26 09:45:00', '2022-09-26 09:45:00', NULL),
(79, 4, '크로스 브라우징 이슈 해결 사례', 'Safari, Chrome, Firefox 등 브라우저마다 다르게 렌더링되는 CSS 및 JS 호환성 문제를 해결했던 경험담입니다.\n\n![크로스 브라우징 이미지](https://picsum.photos/seed/79/600/360)', '2022-09-21 17:10:00', '2022-09-21 17:10:00', NULL),
(80, 0, 'Docker Compose로 다중 컨테이너 관리', 'DB, 백엔드, 프론트엔드 등 여러 컨테이너를 Docker Compose 파일 하나로 정의하고 실행하는 방법을 설명합니다.\n\n![Docker Compose 이미지](https://picsum.photos/seed/80/600/360)', '2022-09-16 12:50:00', '2022-09-16 12:50:00', NULL),
(81, 2, 'RxJS 입문: 리액티브 프로그래밍의 세계', '비동기 데이터 스트림을 처리하는 RxJS의 기본 개념인 Observable, Observer, Operator에 대해 알아봅니다.\n\n![RxJS 이미지](https://picsum.photos/seed/81/600/360)', '2022-09-11 08:40:00', '2022-09-11 08:40:00', NULL),
(82, 1, '나만의 기술 블로그 만들기 (Gatsby vs Jekyll)', '정적 사이트 생성기(SSG)를 이용해 깃허브 페이지에 기술 블로그를 구축하는 과정과 테마 적용법을 공유합니다.\n\n![기술 블로그 이미지](https://picsum.photos/seed/82/600/360)', '2022-09-06 14:25:00', '2022-09-06 14:25:00', NULL),
(83, 3, 'JWT(Json Web Token)의 구조와 보안 취약점', '인증 수단으로 널리 쓰이는 JWT의 Header, Payload, Signature 구조와 탈취 시 위험성, 보안 강화 방법을 다룹니다.\n\n![JWT 이미지](https://picsum.photos/seed/83/600/360)', '2022-09-01 11:35:00', '2022-09-01 11:35:00', NULL),
(84, 4, '리액트 Context API 현명하게 사용하기', '전역 상태 관리를 위해 Context API를 사용할 때 발생하는 불필요한 리렌더링 문제와 이를 최적화하는 팁입니다.\n\n![Context API 이미지](https://picsum.photos/seed/84/600/360)', '2022-08-27 09:15:00', '2022-08-27 09:15:00', NULL),
(85, 0, 'Apache Kafka 기초: 메시지 큐의 이해', '대용량 실시간 데이터 처리를 위한 분산 스트리밍 플랫폼 Kafka의 토픽, 파티션, 컨슈머 그룹 개념을 소개합니다.\n\n![Kafka 이미지](https://picsum.photos/seed/85/600/360)', '2022-08-22 16:30:00', '2022-08-22 16:30:00', NULL),
(86, 2, '코틀린(Kotlin) vs 자바(Java) 문법 비교', '안드로이드 개발의 대세가 된 코틀린이 자바에 비해 가지는 문법적 간결함과 Null Safety 기능을 비교해봅니다.\n\n![Kotlin Java 이미지](https://picsum.photos/seed/86/600/360)', '2022-08-17 10:55:00', '2022-08-17 10:55:00', NULL),
(87, 1, '웹 접근성: 스크린 리더 사용자를 위한 마크업', '시각 장애인이 웹사이트를 이용할 때 필요한 대체 텍스트(alt), ARIA 레이블 등 접근성 준수 가이드입니다.\n\n![웹 접근성 이미지](https://picsum.photos/seed/87/600/360)', '2022-08-12 13:45:00', '2022-08-12 13:45:00', NULL),
(88, 3, '정규 표현식(Regex) 핵심 패턴 10가지', '이메일 검증, 전화번호 포맷팅 등 실무에서 가장 자주 쓰이는 정규 표현식 패턴 10가지를 정리하고 설명합니다.\n\n![정규표현식 이미지](https://picsum.photos/seed/88/600/360)', '2022-08-07 09:05:00', '2022-08-07 09:05:00', NULL),
(89, 4, '서버리스 아키텍처의 한계와 단점', '무조건적인 서버리스 도입이 정답이 아닌 이유, 벤더 종속성(Lock-in) 문제와 디버깅의 어려움에 대해 논합니다.\n\n![서버리스 단점 이미지](https://picsum.photos/seed/89/600/360)', '2022-08-02 15:10:00', '2022-08-02 15:10:00', NULL),
(90, 0, 'MySQL 샤딩(Sharding) 기법 소개', '단일 데이터베이스의 용량 한계를 극복하기 위해 데이터를 여러 DB에 분산 저장하는 샤딩의 개념과 전략을 알아봅니다.\n\n![DB 샤딩 이미지](https://picsum.photos/seed/90/600/360)', '2022-07-28 11:25:00', '2022-07-28 11:25:00', NULL),
(91, 2, 'D3.js로 데이터 시각화하기', '복잡한 데이터를 아름다운 차트와 그래프로 표현할 수 있는 D3.js 라이브러리의 기초 사용법과 예제입니다.\n\n![D3.js 이미지](https://picsum.photos/seed/91/600/360)', '2022-07-23 08:55:00', '2022-07-23 08:55:00', NULL),
(92, 1, 'GitHub Actions로 자동 배포(CD) 구현하기', '메인 브랜치에 코드가 푸시되면 자동으로 AWS S3에 빌드 파일을 업로드하는 워크플로우 작성법을 공유합니다.\n\n![자동 배포 이미지](https://picsum.photos/seed/92/600/360)', '2022-07-18 14:15:00', '2022-07-18 14:15:00', NULL),
(93, 3, '개발자를 위한 타이포그래피 기초', '웹 폰트 선택, 줄 간격(Line-height), 자간 등 가독성 좋은 웹 페이지를 만들기 위한 타이포그래피 팁입니다.\n\n![타이포그래피 이미지](https://picsum.photos/seed/93/600/360)', '2022-07-13 10:40:00', '2022-07-13 10:40:00', NULL),
(94, 4, 'SQL Injection 공격 원리와 방어', '입력폼에 악의적인 SQL문을 삽입하여 정보를 탈취하는 공격 방식과, PreparedStatement를 이용한 방어법을 다룹니다.\n\n![보안 이미지](https://picsum.photos/seed/94/600/360)', '2022-07-08 16:25:00', '2022-07-08 16:25:00', NULL),
(95, 0, 'Vim 에디터: 입문에서 활용까지', '마우스 없이 코딩하는 속도를 경험해보고 싶은 개발자를 위한 Vim 필수 단축키와 설정(.vimrc) 가이드입니다.\n\n![Vim 이미지](https://picsum.photos/seed/95/600/360)', '2022-07-03 12:05:00', '2022-07-03 12:05:00', NULL),
(96, 2, '모바일 앱 성능 최적화 체크리스트', '앱 구동 속도 향상, 배터리 소모 감소, 메모리 누수 방지를 위해 모바일 개발자가 점검해야 할 항목들입니다.\n\n![앱 최적화 이미지](https://picsum.photos/seed/96/600/360)', '2022-06-28 09:35:00', '2022-06-28 09:35:00', NULL),
(97, 1, 'CSS Grid Layout 완벽 가이드', '2차원 레이아웃 시스템인 Grid의 fr 단위, template-areas 등 핵심 속성을 통해 복잡한 웹 레이아웃을 잡는 법을 배웁니다.\n\n![CSS Grid 이미지](https://picsum.photos/seed/97/600/360)', '2022-06-23 15:00:00', '2022-06-23 15:00:00', NULL),
(98, 3, '개발 팀의 코드 리뷰 문화 개선하기', '단순한 지적을 넘어 성장을 돕는 코드 리뷰 문화를 만들기 위한 피드백 방법과 리뷰 규칙(Rule) 설정 제안입니다.\n\n![코드 리뷰 문화 이미지](https://picsum.photos/seed/98/600/360)', '2022-06-18 11:45:00', '2022-06-18 11:45:00', NULL),
(99, 4, '기술 부채(Technical Debt) 관리 전략', '빠른 개발을 위해 타협했던 코드 품질 문제를 언제, 어떻게 갚아나가야 할지 리팩토링 계획 수립 방법을 논의합니다.\n\n![기술 부채 이미지](https://picsum.photos/seed/99/600/360)', '2022-06-13 08:10:00', '2022-06-13 08:10:00', NULL),
(100, 0, '2025년 미래 기술 트렌드 예측', 'AI 코딩 어시스턴트의 발전, 퀀텀 컴퓨팅의 가능성 등 향후 3년간 소프트웨어 업계에 불어올 변화를 예측해봅니다.\n\n![미래 기술 이미지](https://picsum.photos/seed/100/600/360)', '2022-06-08 17:30:00', '2022-06-08 17:30:00', NULL),
(101, 1, 'Remix 프레임워크 첫인상 리뷰', 'React Router 팀이 만든 풀스택 웹 프레임워크 Remix의 데이터 로딩 방식과 사용자 경험 중심의 철학을 분석해봅니다.\n\n![Remix 이미지](https://picsum.photos/seed/101/600/360)', '2022-05-30 10:00:00', '2022-05-30 10:00:00', NULL),
(102, 3, 'C++ 모던 문법 (C++11 ~ C++20)', '스마트 포인터, 람다 표현식, 모듈 시스템 등 C++을 더 안전하고 강력하게 만들어준 현대적인 기능들을 정리했습니다.\n\n![C++ 이미지](https://picsum.photos/seed/102/600/360)', '2022-05-25 14:30:00', '2022-05-25 14:30:00', NULL),
(103, 4, '피그마 플러그인 개발 입문', '디자인 업무 자동화를 위해 TypeScript와 Figma API를 사용하여 나만의 플러그인을 만드는 과정을 소개합니다.\n\n![피그마 플러그인 이미지](https://picsum.photos/seed/103/600/360)', '2022-05-20 09:15:00', '2022-05-20 09:15:00', NULL),
(104, 2, 'React Native 성능 최적화 팁', 'JS 브릿지 병목을 줄이는 방법, FlatList 최적화, Hermes 엔진 도입 등 앱 버벅임을 줄이는 실전 노하우입니다.\n\n![React Native 이미지](https://picsum.photos/seed/104/600/360)', '2022-05-15 16:40:00', '2022-05-15 16:40:00', NULL),
(105, 0, '네트워크 기초: TCP 3-way Handshake', '신뢰성 있는 연결을 수립하기 위한 TCP 프로토콜의 핵심 과정인 3-way Handshake와 연결 종료 과정을 상세히 설명합니다.\n\n![TCP 이미지](https://picsum.photos/seed/105/600/360)', '2022-05-10 11:00:00', '2022-05-10 11:00:00', NULL),
(106, 2, '클라우드 비용 아끼는 Spot Instance 활용법', 'AWS EC2 스팟 인스턴스를 활용하여 서버 비용을 최대 90%까지 절감하는 전략과 중단 시 대처 방안을 공유합니다.\n\n![AWS Spot Instance 이미지](https://picsum.photos/seed/106/600/360)', '2022-05-05 08:30:00', '2022-05-05 08:30:00', NULL),
(107, 1, 'JavaScript 프로토타입 이해하기', '클래스 문법 이면에 숨겨진 자바스크립트의 본질, 프로토타입 체인과 상속의 동작 원리를 깊이 있게 파헤칩니다.\n\n![JS 프로토타입 이미지](https://picsum.photos/seed/107/600/360)', '2022-04-30 13:20:00', '2022-04-30 13:20:00', NULL),
(108, 3, '개발자를 위한 글쓰기 가이드', '기술 블로그를 운영하거나 사내 문서를 작성할 때 논리적이고 명확하게 의사를 전달하는 글쓰기 원칙 5가지입니다.\n\n![글쓰기 이미지](https://picsum.photos/seed/108/600/360)', '2022-04-25 10:50:00', '2022-04-25 10:50:00', NULL),
(109, 4, 'MongoDB Aggregation Pipeline 활용', '복잡한 데이터 집계 처리를 위해 MongoDB의 Aggregation 프레임워크를 사용하는 방법과 주요 스테이지($match, $group) 설명입니다.\n\n![MongoDB 이미지](https://picsum.photos/seed/109/600/360)', '2022-04-20 15:10:00', '2022-04-20 15:10:00', NULL),
(110, 0, 'Shell Script 자동화 예제 모음', '로그 파일 백업, 배포 스크립트 작성 등 서버 관리자가 자주 사용하는 유용한 쉘 스크립트 예제들을 모았습니다.\n\n![Shell Script 이미지](https://picsum.photos/seed/110/600/360)', '2022-04-15 09:00:00', '2022-04-15 09:00:00', NULL),
(111, 2, 'Flutter 상태 관리: Provider vs Riverpod', 'Flutter 생태계에서 가장 인기 있는 두 상태 관리 라이브러리의 차이점과 Riverpod이 해결하고자 한 Provider의 단점입니다.\n\n![Flutter 상태관리 이미지](https://picsum.photos/seed/111/600/360)', '2022-04-10 17:00:00', '2022-04-10 17:00:00', NULL),
(112, 1, '웹소켓(WebSocket) vs SSE(Server-Sent Events)', '실시간 통신 기술을 선택할 때 고려해야 할 양방향 통신의 필요성, 재연결 처리, 브라우저 호환성 등을 비교합니다.\n\n![실시간 통신 이미지](https://picsum.photos/seed/112/600/360)', '2022-04-05 12:30:00', '2022-04-05 12:30:00', NULL),
(113, 3, 'Swift 언어의 Optional 개념 잡기', 'iOS 개발의 핵심인 Optional 타입의 등장 배경과 옵셔널 바인딩, 체이닝 등 안전하게 값을 추출하는 방법들입니다.\n\n![Swift Optional 이미지](https://picsum.photos/seed/113/600/360)', '2022-03-31 08:45:00', '2022-03-31 08:45:00', NULL),
(114, 4, 'Google Analytics 4 (GA4) 도입 가이드', '유니버설 애널리틱스(UA) 종료에 대비하여 GA4로 전환하는 방법과 이벤트 기반 데이터 모델링의 차이를 설명합니다.\n\n![GA4 이미지](https://picsum.photos/seed/114/600/360)', '2022-03-26 14:15:00', '2022-03-26 14:15:00', NULL),
(115, 0, '자료구조: 해시 테이블(Hash Table)의 원리', '빠른 데이터 검색을 가능하게 하는 해시 함수의 원리와 해시 충돌(Collision)을 해결하는 체이닝, 개방 주소법을 알아봅니다.\n\n![자료구조 이미지](https://picsum.photos/seed/115/600/360)', '2022-03-21 10:20:00', '2022-03-21 10:20:00', NULL),
(116, 2, 'CSS Flexbox 게임으로 배우기', '헷갈리는 justify-content, align-items 속성을 직관적인 예제와 게임 형식으로 마스터하는 튜토리얼입니다.\n\n![Flexbox 이미지](https://picsum.photos/seed/116/600/360)', '2022-03-16 16:00:00', '2022-03-16 16:00:00', NULL),
(117, 1, 'NestJS: 엔터프라이즈급 Node.js 프레임워크', 'Express 위에서 구조적인 아키텍처를 제공하는 NestJS의 모듈, 컨트롤러, 서비스 패턴과 DI(의존성 주입) 시스템을 소개합니다.\n\n![NestJS 이미지](https://picsum.photos/seed/117/600/360)', '2022-03-11 09:30:00', '2022-03-11 09:30:00', NULL),
(118, 3, '개발자 면접 단골 질문: 프로세스와 스레드', '운영체제의 기본 개념인 프로세스와 스레드의 차이, 멀티 프로세싱과 멀티 스레딩의 장단점을 면접 답변용으로 정리합니다.\n\n![OS 이미지](https://picsum.photos/seed/118/600/360)', '2022-03-06 13:50:00', '2022-03-06 13:50:00', NULL),
(119, 4, '피싱 방지를 위한 이메일 보안 설정 (SPF, DKIM, DMARC)', '서비스에서 발송하는 메일이 스팸으로 분류되지 않도록 하는 필수 도메인 인증 설정 방법입니다.\n\n![이메일 보안 이미지](https://picsum.photos/seed/119/600/360)', '2022-03-01 11:10:00', '2022-03-01 11:10:00', NULL),
(120, 0, '파이썬 가상환경 관리: venv vs poetry', '패키지 의존성 관리를 위한 도구 비교. 단순한 venv 사용법과 강력한 의존성 해결 기능을 가진 Poetry 도입기를 다룹니다.\n\n![Python 가상환경 이미지](https://picsum.photos/seed/120/600/360)', '2022-02-24 08:20:00', '2022-02-24 08:20:00', NULL),
(121, 2, 'UI 디자인의 게슈탈트 원리', '사용자가 인터페이스를 그룹화하여 인식하는 심리학적 법칙(근접성, 유사성 등)을 UI 디자인에 적용하는 사례입니다.\n\n![게슈탈트 이론 이미지](https://picsum.photos/seed/121/600/360)', '2022-02-19 15:40:00', '2022-02-19 15:40:00', NULL),
(122, 1, 'Ansible로 서버 설정 자동화하기', '인프라 구성을 코드로 관리(IaC)하는 도구 중 하나인 Ansible의 Playbook 작성법과 에이전트리스 방식의 장점입니다.\n\n![Ansible 이미지](https://picsum.photos/seed/122/600/360)', '2022-02-14 10:00:00', '2022-02-14 10:00:00', NULL),
(123, 3, 'Effective Java: 정적 팩토리 메서드', '생성자 대신 정적 팩토리 메서드를 사용해야 하는 이유와 장점(이름 가짐, 호출 시마다 인스턴스 생성 안 함 등)을 설명합니다.\n\n![Java 이미지](https://picsum.photos/seed/123/600/360)', '2022-02-09 14:25:00', '2022-02-09 14:25:00', NULL),
(124, 4, '브라우저 렌더링 과정 (Critical Rendering Path)', 'HTML 파싱부터 DOM 트리 생성, 레이아웃, 페인트까지 브라우저가 화면을 그리는 과정을 이해하고 최적화 포인트를 찾습니다.\n\n![브라우저 렌더링 이미지](https://picsum.photos/seed/124/600/360)', '2022-02-04 09:05:00', '2022-02-04 09:05:00', NULL),
(125, 0, 'No-Code 툴 Bubble 사용기', '코딩 없이 복잡한 로직의 웹 서비스를 만들 수 있는 버블(Bubble)의 가능성과 한계, 그리고 실제 프로젝트 적용 사례입니다.\n\n![No-Code 이미지](https://picsum.photos/seed/125/600/360)', '2022-01-30 16:55:00', '2022-01-30 16:55:00', NULL),
(126, 2, 'SQL Join 시각화해서 이해하기', 'Inner Join, Left Join, Outer Join 등의 집합 관계를 벤 다이어그램과 예시 데이터로 명확하게 정리합니다.\n\n![SQL Join 이미지](https://picsum.photos/seed/126/600/360)', '2022-01-25 11:30:00', '2022-01-25 11:30:00', NULL),
(127, 1, '모바일 퍼스트 디자인이란?', '데스크탑보다 모바일 화면을 먼저 기획하는 디자인 전략의 중요성과 미디어 쿼리 작성 순서에 대해 설명합니다.\n\n![모바일 퍼스트 이미지](https://picsum.photos/seed/127/600/360)', '2022-01-20 08:50:00', '2022-01-20 08:50:00', NULL),
(128, 3, 'REST API 디자인 가이드라인', '자원(Resource) 중심의 URI 설계, 적절한 HTTP 메서드 사용, 상태 코드 반환 등 깔끔한 API를 설계하는 원칙들입니다.\n\n![REST API 이미지](https://picsum.photos/seed/128/600/360)', '2022-01-15 13:10:00', '2022-01-15 13:10:00', NULL),
(129, 4, 'Unity 3D 게임 개발 입문', '유니티 엔진의 인터페이스 소개와 C# 스크립트를 이용해 간단한 캐릭터 이동 기능을 구현하는 튜토리얼입니다.\n\n![Unity 이미지](https://picsum.photos/seed/129/600/360)', '2022-01-10 10:45:00', '2022-01-10 10:45:00', NULL),
(130, 0, '리눅스 권한 관리 (chmod, chown)', '리눅스 파일 시스템의 읽기/쓰기/실행 권한 개념과 755, 644 등 숫자로 권한을 설정하는 방법을 알아봅니다.\n\n![리눅스 권한 이미지](https://picsum.photos/seed/130/600/360)', '2022-01-05 15:30:00', '2022-01-05 15:30:00', NULL),
(131, 2, 'TypeScript 유틸리티 타입 정복', 'Pick, Omit, Partial, Required 등 복잡한 타입을 쉽게 조작할 수 있게 해주는 TS 내장 유틸리티 타입 사용법입니다.\n\n![TypeScript 이미지](https://picsum.photos/seed/131/600/360)', '2021-12-31 09:15:00', '2021-12-31 09:15:00', NULL),
(132, 1, 'Docker 이미지 경량화 전략', 'Multi-stage build 사용, Alpine 리눅스 기반 이미지 선택 등 도커 이미지 크기를 줄여 배포 속도를 높이는 팁입니다.\n\n![Docker 이미지](https://picsum.photos/seed/132/600/360)', '2021-12-26 14:00:00', '2021-12-26 14:00:00', NULL),
(133, 3, '개발자의 사이드 프로젝트 아이디어 10선', '기술력을 향상시키고 포트폴리오에 도움이 되는 현실적이고 재미있는 사이드 프로젝트 주제들을 추천합니다.\n\n![사이드 프로젝트 이미지](https://picsum.photos/seed/133/600/360)', '2021-12-21 11:20:00', '2021-12-21 11:20:00', NULL),
(134, 4, 'HTTP/2의 멀티플렉싱과 헤더 압축', 'HTTP/1.1의 HOL Blocking 문제를 해결한 HTTP/2의 핵심 기술과 이를 통해 얻을 수 있는 성능 이점을 설명합니다.\n\n![HTTP/2 이미지](https://picsum.photos/seed/134/600/360)', '2021-12-16 08:35:00', '2021-12-16 08:35:00', NULL),
(135, 0, '안드로이드 Jetpack Compose 시작하기', 'XML 없이 코틀린 코드로 UI를 구성하는 안드로이드의 최신 UI 툴킷, Jetpack Compose의 기초를 다룹니다.\n\n![Jetpack Compose 이미지](https://picsum.photos/seed/135/600/360)', '2021-12-11 16:10:00', '2021-12-11 16:10:00', NULL),
(136, 2, '프론트엔드 테스트: Cypress vs Jest', 'E2E 테스트 도구인 Cypress와 단위 테스트 도구인 Jest의 차이점과 각각의 역할에 맞는 사용 시나리오를 소개합니다.\n\n![FE 테스트 이미지](https://picsum.photos/seed/136/600/360)', '2021-12-06 10:25:00', '2021-12-06 10:25:00', NULL),
(137, 1, 'PostgreSQL의 JSONB 데이터 타입 활용', 'RDBMS인 PostgreSQL에서 NoSQL처럼 유연하게 JSON 데이터를 저장하고 쿼리하는 방법과 성능 고려사항입니다.\n\n![PostgreSQL 이미지](https://picsum.photos/seed/137/600/360)', '2021-12-01 13:40:00', '2021-12-01 13:40:00', NULL),
(138, 3, '객체지향 생활 체조 원칙 9가지', '한 메서드에 오직 한 단계의 들여쓰기만 한다, else 예약어를 쓰지 않는다 등 좋은 코드를 작성하기 위한 훈련 수칙입니다.\n\n![OOP 이미지](https://picsum.photos/seed/138/600/360)', '2021-11-26 09:50:00', '2021-11-26 09:50:00', NULL),
(139, 4, 'UX 법칙: 힉의 법칙과 피츠의 법칙', '선택지의 수와 목표물까지의 거리가 사용자 결정 시간에 미치는 영향을 설명하는 고전적인 UX 원칙입니다.\n\n![UX 법칙 이미지](https://picsum.photos/seed/139/600/360)', '2021-11-21 15:15:00', '2021-11-21 15:15:00', NULL),
(140, 0, 'Git 커밋 메시지 컨벤션 (Angular Style)', 'feat, fix, docs 등 말머리를 사용하여 협업 시 가독성을 높이는 커밋 메시지 작성 규칙을 정리했습니다.\n\n![Git 컨벤션 이미지](https://picsum.photos/seed/140/600/360)', '2021-11-16 11:00:00', '2021-11-16 11:00:00', NULL),
(141, 2, '반응형 이미지를 위한 srcset과 sizes', '디바이스 해상도와 화면 크기에 따라 최적화된 이미지를 브라우저가 선택해서 로딩하게 만드는 HTML 속성 활용법입니다.\n\n![반응형 이미지](https://picsum.photos/seed/141/600/360)', '2021-11-11 08:30:00', '2021-11-11 08:30:00', NULL),
(142, 1, 'Java Garbage Collection (GC) 동작 원리', 'Young/Old Generation의 구분, Stop-the-world 현상 등 자바 메모리 관리의 핵심인 GC의 알고리즘을 알아봅니다.\n\n![Java GC 이미지](https://picsum.photos/seed/142/600/360)', '2021-11-06 17:00:00', '2021-11-06 17:00:00', NULL),
(143, 3, '개발자 번역 활동의 장점', '해외 기술 문서를 번역하며 얻는 기술적 깊이와 커뮤니티 기여의 보람, 그리고 번역 시 주의할 점을 공유합니다.\n\n![번역 이미지](https://picsum.photos/seed/143/600/360)', '2021-11-01 10:10:00', '2021-11-01 10:10:00', NULL),
(144, 4, 'Sass(SCSS) 믹스인과 변수 활용', 'CSS 전처리기를 사용하여 스타일 코드의 재사용성을 높이고 유지보수를 쉽게 만드는 SCSS의 핵심 기능 소개입니다.\n\n![Sass 이미지](https://picsum.photos/seed/144/600/360)', '2021-10-27 14:50:00', '2021-10-27 14:50:00', NULL),
(145, 0, 'OAuth 2.0 흐름 완벽 정리', 'Authorization Code Grant 타입을 중심으로 클라이언트, 인증 서버, 리소스 서버 간의 토큰 교환 흐름을 도식화합니다.\n\n![OAuth 흐름 이미지](https://picsum.photos/seed/145/600/360)', '2021-10-22 09:20:00', '2021-10-22 09:20:00', NULL),
(146, 2, '파이썬 데코레이터(Decorator) 이해하기', '함수를 인자로 받아 기능을 확장하는 데코레이터의 문법(@)과 클로저 개념을 활용한 구현 원리를 설명합니다.\n\n![Python Decorator 이미지](https://picsum.photos/seed/146/600/360)', '2021-10-17 16:30:00', '2021-10-17 16:30:00', NULL),
(147, 1, 'CDN(Content Delivery Network)의 원리', '전 세계에 분산된 서버를 통해 사용자에게 컨텐츠를 빠르게 전송하는 CDN의 캐싱 원리와 적용 효과를 알아봅니다.\n\n![CDN 이미지](https://picsum.photos/seed/147/600/360)', '2021-10-12 11:40:00', '2021-10-12 11:40:00', NULL),
(148, 3, 'Ruby on Rails: 여전히 강력한가?', '빠른 MVP 개발의 대명사인 레일즈의 현재 위치와 스타트업 초기 단계에서의 유효성에 대한 고찰입니다.\n\n![Ruby on Rails 이미지](https://picsum.photos/seed/148/600/360)', '2021-10-07 08:50:00', '2021-10-07 08:50:00', NULL),
(149, 4, '웹 폰트 최적화 (FOIT, FOUT 방지)', '웹 폰트 로딩 시 텍스트가 깜빡이거나 폰트가 늦게 바뀌는 현상을 막기 위한 `font-display` 속성과 최적화 팁입니다.\n\n![웹 폰트 이미지](https://picsum.photos/seed/149/600/360)', '2021-10-02 13:00:00', '2021-10-02 13:00:00', NULL),
(150, 0, '블록체인 기초: 해시와 원장', '암호화폐의 기반 기술인 블록체인의 무결성을 보장하는 해시 연결 구조와 분산 원장 기술의 개념을 쉽게 설명합니다.\n\n![블록체인 이미지](https://picsum.photos/seed/150/600/360)', '2021-09-27 10:00:00', '2021-09-27 10:00:00', NULL),
(151, 2, 'TDD(테스트 주도 개발) 시작하기', '실패하는 테스트를 먼저 작성하고 코드를 구현하는 Red-Green-Refactor 사이클의 개념과 TDD의 이점을 소개합니다.\n\n![TDD 이미지](https://picsum.photos/seed/151/600/360)', '2021-09-22 15:20:00', '2021-09-22 15:20:00', NULL),
(152, 1, 'iOS 오토 레이아웃의 제약조건(Constraints)', '다양한 아이폰 화면 크기에 대응하기 위해 뷰 간의 관계와 제약조건을 설정하는 오토 레이아웃의 기본 원리입니다.\n\n![Auto Layout 이미지](https://picsum.photos/seed/152/600/360)', '2021-09-17 09:40:00', '2021-09-17 09:40:00', NULL),
(153, 3, 'SQL 윈도우 함수(Window Function) 활용', '`ROW_NUMBER`, `RANK`, `LEAD` 등 행 간의 관계를 정의하여 복잡한 분석 쿼리를 간단하게 만드는 방법을 다룹니다.\n\n![SQL Window Function 이미지](https://picsum.photos/seed/153/600/360)', '2021-09-12 14:10:00', '2021-09-12 14:10:00', NULL),
(154, 4, '피그마 컴포넌트 프로퍼티(Variants) 활용', '버튼의 상태(Hover, Active)나 종류(Primary, Secondary)를 체계적으로 관리하는 Variants 기능 사용법입니다.\n\n![Figma Variants 이미지](https://picsum.photos/seed/154/600/360)', '2021-09-07 10:30:00', '2021-09-07 10:30:00', NULL),
(155, 0, 'DevOps 엔지니어의 역할과 필요 역량', '개발과 운영의 가교 역할을 하는 데브옵스 엔지니어에게 요구되는 기술 스택(CI/CD, 클라우드, 스크립팅)과 마인드셋입니다.\n\n![DevOps 이미지](https://picsum.photos/seed/155/600/360)', '2021-09-02 08:20:00', '2021-09-02 08:20:00', NULL),
(156, 2, '자바스크립트 비동기 처리: Callback부터 Async/Await까지', '콜백 지옥의 문제점과 이를 해결하기 위해 등장한 Promise, 그리고 동기 코드처럼 작성 가능한 Async/Await의 진화 과정입니다.\n\n![JS 비동기 이미지](https://picsum.photos/seed/156/600/360)', '2021-08-28 17:00:00', '2021-08-28 17:00:00', NULL),
(157, 1, 'Redis 데이터 타입 5가지와 활용 사례', 'String, List, Set, Hash, Sorted Set 등 레디스의 주요 데이터 구조 특징과 각각의 적절한 사용처를 정리합니다.\n\n![Redis Type 이미지](https://picsum.photos/seed/157/600/360)', '2021-08-23 11:50:00', '2021-08-23 11:50:00', NULL),
(158, 3, '개발자를 위한 팁: 질문 잘하는 법', '문제를 해결하지 못했을 때 커뮤니티나 동료에게 효과적으로 질문하여 빠르게 답변을 얻는 노하우(재현 방법, 시도한 것 등)입니다.\n\n![질문하는 법 이미지](https://picsum.photos/seed/158/600/360)', '2021-08-18 09:10:00', '2021-08-18 09:10:00', NULL),
(159, 4, 'CSR, SSR, SSG 렌더링 방식 비교', 'Client-side Rendering, Server-side Rendering, Static Site Generation의 장단점과 프로젝트 성격에 따른 선택 기준입니다.\n\n![렌더링 방식 이미지](https://picsum.photos/seed/159/600/360)', '2021-08-13 15:40:00', '2021-08-13 15:40:00', NULL),
(160, 0, 'AWS S3 정적 웹사이트 호스팅', '별도의 서버 구축 없이 S3 버킷만을 이용하여 HTML/CSS/JS로 이루어진 정적 웹사이트를 배포하는 방법입니다.\n\n![AWS S3 이미지](https://picsum.photos/seed/160/600/360)', '2021-08-08 10:00:00', '2021-08-08 10:00:00', NULL),
(161, 2, '파이썬 리스트 컴프리헨션(List Comprehension)', '반복문과 조건문을 한 줄로 표현하여 리스트를 생성하는 파이썬 고유의 간결하고 강력한 문법을 연습합니다.\n\n![Python 문법 이미지](https://picsum.photos/seed/161/600/360)', '2021-08-03 13:30:00', '2021-08-03 13:30:00', NULL),
(162, 1, 'Git Cherry-pick 명령어 활용', '다른 브랜치의 특정 커밋 하나만 내 브랜치로 가져오고 싶을 때 사용하는 체리픽 명령어의 사용법과 주의점입니다.\n\n![Git Cherry-pick 이미지](https://picsum.photos/seed/162/600/360)', '2021-07-29 08:45:00', '2021-07-29 08:45:00', NULL),
(163, 3, 'JPA N+1 문제 원인과 해결', 'ORM 사용 시 흔히 발생하는 성능 이슈인 N+1 문제의 발생 원리를 이해하고 Fetch Join 등을 통한 해결책을 제시합니다.\n\n![JPA 이미지](https://picsum.photos/seed/163/600/360)', '2021-07-24 16:15:00', '2021-07-24 16:15:00', NULL),
(164, 4, '마이크로 프론트엔드(Micro-Frontends) 개념', '백엔드의 MSA 개념을 프론트엔드에 적용하여, 거대한 웹 앱을 독립적인 기능 단위로 쪼개 개발하는 아키텍처입니다.\n\n![MFE 이미지](https://picsum.photos/seed/164/600/360)', '2021-07-19 11:20:00', '2021-07-19 11:20:00', NULL),
(165, 0, 'IntelliJ IDEA 필수 단축키 모음', '생산성을 2배로 높여주는 젯브레인 IDE의 검색, 리팩토링, 코드 생성 관련 핵심 단축키들을 정리했습니다.\n\n![IntelliJ 이미지](https://picsum.photos/seed/165/600/360)', '2021-07-14 09:00:00', '2021-07-14 09:00:00', NULL),
(166, 2, '리액트 Hooks: useEffect 완벽 가이드', '의존성 배열(dependency array) 관리, 클린업 함수 등 useEffect 훅을 올바르게 사용하여 사이드 이펙트를 제어하는 법입니다.\n\n![React Hooks 이미지](https://picsum.photos/seed/166/600/360)', '2021-07-09 14:50:00', '2021-07-09 14:50:00', NULL),
(167, 1, 'HTTP 상태 코드 101: 200부터 500까지', '200 OK, 404 Not Found, 500 Internal Server Error 등 개발자가 알아야 할 주요 HTTP 상태 코드의 의미입니다.\n\n![HTTP 상태 코드 이미지](https://picsum.photos/seed/167/600/360)', '2021-07-04 10:30:00', '2021-07-04 10:30:00', NULL),
(168, 3, '스크럼(Scrum) 회의: 데일리 스탠드업', '짧은 시간 동안 어제 한 일, 오늘 할 일, 방해 요소를 공유하여 팀의 싱크를 맞추는 효과적인 스탠드업 미팅 요령입니다.\n\n![스크럼 이미지](https://picsum.photos/seed/168/600/360)', '2021-06-29 08:20:00', '2021-06-29 08:20:00', NULL),
(169, 4, 'CSS 변수(Custom Properties) 활용', '`:root` 가상 클래스에 변수를 선언하고 재사용하여 테마 변경(다크 모드) 등을 쉽게 구현하는 CSS 변수 사용법입니다.\n\n![CSS 변수 이미지](https://picsum.photos/seed/169/600/360)', '2021-06-24 15:10:00', '2021-06-24 15:10:00', NULL),
(170, 0, '파이썬 데이터 분석: Numpy 기초', '고성능 수치 계산을 위한 라이브러리인 Numpy의 배열 생성, 연산, 인덱싱 등 기초적인 사용법을 다룹니다.\n\n![Numpy 이미지](https://picsum.photos/seed/170/600/360)', '2021-06-19 11:40:00', '2021-06-19 11:40:00', NULL),
(171, 2, 'API 게이트웨이의 역할과 필요성', '마이크로서비스 아키텍처에서 요청 라우팅, 인증, 속도 제한 등을 통합 관리하는 API 게이트웨이의 기능을 설명합니다.\n\n![API Gateway 이미지](https://picsum.photos/seed/171/600/360)', '2021-06-14 09:50:00', '2021-06-14 09:50:00', NULL),
(172, 1, '자바스크립트 클로저(Closure) 쉽게 이해하기', '외부 함수가 종료된 후에도 내부 함수가 외부 변수에 접근할 수 있는 클로저의 개념과 활용 패턴을 예제로 알아봅니다.\n\n![Closure 이미지](https://picsum.photos/seed/172/600/360)', '2021-06-09 13:20:00', '2021-06-09 13:20:00', NULL),
(173, 3, '개발자의 건강: 손목 터널 증후군 예방', '하루 종일 키보드를 치는 개발자를 위협하는 손목 통증의 원인과 스트레칭, 인체공학적 장비 선택 가이드입니다.\n\n![손목 건강 이미지](https://picsum.photos/seed/173/600/360)', '2021-06-04 08:40:00', '2021-06-04 08:40:00', NULL),
(174, 4, 'Next.js의 getStaticProps와 getServerSideProps', '정적 생성(SSG)과 서버 사이드 렌더링(SSR)을 위한 Next.js의 데이터 페칭 함수들의 차이점과 사용 시기입니다.\n\n![Next.js Data Fetching 이미지](https://picsum.photos/seed/174/600/360)', '2021-05-30 16:30:00', '2021-05-30 16:30:00', NULL),
(175, 0, 'GitHub 프로필 꾸미기 (Readme.md)', '매력적인 깃허브 프로필을 만들기 위해 Readme.md 파일에 배지, 통계 그래프, 기술 스택 아이콘을 추가하는 법입니다.\n\n![GitHub Profile 이미지](https://picsum.photos/seed/175/600/360)', '2021-05-25 10:15:00', '2021-05-25 10:15:00', NULL),
(176, 2, 'SQL vs NoSQL: 초보자를 위한 비교', '관계형 데이터베이스와 비관계형 데이터베이스의 구조적 차이와 각각 어떤 프로젝트에 적합한지 비교 분석합니다.\n\n![DB 비교 이미지](https://picsum.photos/seed/176/600/360)', '2021-05-20 14:00:00', '2021-05-20 14:00:00', NULL),
(177, 1, '웹팩(Webpack) 기초 설정 가이드', '모듈 번들러인 웹팩의 Entry, Output, Loader, Plugin 등 핵심 개념을 이해하고 기본 설정 파일을 작성해봅니다.\n\n![Webpack 이미지](https://picsum.photos/seed/177/600/360)', '2021-05-15 09:30:00', '2021-05-15 09:30:00', NULL),
(178, 3, 'C언어 포인터(Pointer) 개념 잡기', '메모리 주소를 직접 다루는 포인터 변수의 선언과 참조 연산자(*), 주소 연산자(&)의 역할을 그림으로 설명합니다.\n\n![C언어 포인터 이미지](https://picsum.photos/seed/178/600/360)', '2021-05-10 17:10:00', '2021-05-10 17:10:00', NULL),
(179, 4, 'Svelte 프레임워크 찍먹하기', '가상 돔 없이 컴파일 타임에 최적화된 바닐라 JS를 생성하는 스벨트(Svelte)의 직관적인 문법과 특징을 살펴봅니다.\n\n![Svelte 이미지](https://picsum.photos/seed/179/600/360)', '2021-05-05 11:55:00', '2021-05-05 11:55:00', NULL),
(180, 0, '터미널 커스터마이징: Oh My Zsh', '맥/리눅스 터미널을 예쁘고 편리하게 만들기 위해 iTerm2, Zsh, Oh My Zsh 및 테마/플러그인을 설치하는 과정입니다.\n\n![Terminal 이미지](https://picsum.photos/seed/180/600/360)', '2021-04-30 08:30:00', '2021-04-30 08:30:00', NULL),
(181, 2, 'React Virtual DOM(가상 돔)이란?', '리액트가 실제 DOM 조작을 최소화하여 성능을 최적화하기 위해 사용하는 가상 돔의 비교 알고리즘(Diffing)을 설명합니다.\n\n![Virtual DOM 이미지](https://picsum.photos/seed/181/600/360)', '2021-04-25 15:45:00', '2021-04-25 15:45:00', NULL),
(182, 1, '서버 인증 방식: 세션 vs 토큰', '전통적인 세션 기반 인증과 JWT 등을 이용한 토큰 기반 인증의 동작 방식 차이와 장단점을 비교합니다.\n\n![인증 방식 이미지](https://picsum.photos/seed/182/600/360)', '2021-04-20 10:20:00', '2021-04-20 10:20:00', NULL),
(183, 3, '주니어 개발자의 실수 회고', '입사 초기 프로덕션 DB를 날릴 뻔했던 아찔한 경험과, 그를 통해 배운 안전 장치와 프로세스의 중요성입니다.\n\n![실수 회고 이미지](https://picsum.photos/seed/183/600/360)', '2021-04-15 13:00:00', '2021-04-15 13:00:00', NULL),
(184, 4, 'BEM 방법론으로 CSS 클래스 작명하기', 'Block, Element, Modifier 구조로 CSS 클래스 이름을 체계적으로 짓는 BEM 네이밍 컨벤션을 소개합니다.\n\n![BEM 이미지](https://picsum.photos/seed/184/600/360)', '2021-04-10 09:05:00', '2021-04-10 09:05:00', NULL),
(185, 0, '파이썬 셀레니움(Selenium) 웹 크롤링', '브라우저를 자동으로 제어하여 동적인 웹 페이지의 데이터를 수집하는 셀레니움 라이브러리의 기초 사용법입니다.\n\n![Selenium 이미지](https://picsum.photos/seed/185/600/360)', '2021-04-05 16:20:00', '2021-04-05 16:20:00', NULL),
(186, 2, '디자인 패턴: 옵저버(Observer) 패턴', '상태 변화가 일어났을 때 객체들에게 자동으로 알림을 보내는 옵저버 패턴의 개념과 구현 예제(이벤트 리스너 등)입니다.\n\n![Observer Pattern 이미지](https://picsum.photos/seed/186/600/360)', '2021-03-31 11:10:00', '2021-03-31 11:10:00', NULL),
(187, 1, '리눅스 SSH 접속과 키 관리', '원격 서버에 안전하게 접속하기 위한 SSH 프로토콜 사용법과 비밀번호 대신 SSH Key Pair를 생성하여 인증하는 법입니다.\n\n![SSH 이미지](https://picsum.photos/seed/187/600/360)', '2021-03-26 08:50:00', '2021-03-26 08:50:00', NULL),
(188, 3, 'Notion으로 협업 페이지 만들기', '노션을 단순한 메모장이 아닌 팀 위키, 칸반 보드, 일정 관리 도구로 활용하는 팁과 템플릿 제작 방법입니다.\n\n![Notion 이미지](https://picsum.photos/seed/188/600/360)', '2021-03-21 14:30:00', '2021-03-21 14:30:00', NULL),
(189, 4, 'HTML5 시맨틱 태그(Semantic Tag)', 'header, nav, article, footer 등 의미론적 태그를 사용하여 검색 엔진과 스크린 리더 친화적인 마크업을 하는 이유입니다.\n\n![Semantic Web 이미지](https://picsum.photos/seed/189/600/360)', '2021-03-16 10:00:00', '2021-03-16 10:00:00', NULL),
(190, 0, 'REST API 테스트 도구: Postman 기초', 'API 개발 및 디버깅 필수품인 포스트맨으로 GET/POST 요청을 보내고 응답을 검증하는 기본적인 사용법입니다.\n\n![Postman 이미지](https://picsum.photos/seed/190/600/360)', '2021-03-11 15:50:00', '2021-03-11 15:50:00', NULL),
(191, 2, '자바스크립트 화살표 함수(Arrow Function)', 'ES6에 도입된 화살표 함수의 간결한 문법과 기존 함수 표현식과의 결정적 차이(this 바인딩 등)를 설명합니다.\n\n![Arrow Function 이미지](https://picsum.photos/seed/191/600/360)', '2021-03-06 09:20:00', '2021-03-06 09:20:00', NULL),
(192, 1, '데이터베이스 트랜잭션(Transaction) ACID', '데이터 무결성을 보장하기 위한 트랜잭션의 4가지 성질인 원자성, 일관성, 고립성, 지속성에 대해 알아봅니다.\n\n![DB Transaction 이미지](https://picsum.photos/seed/192/600/360)', '2021-03-01 13:40:00', '2021-03-01 13:40:00', NULL),
(193, 3, '개발자 컨퍼런스 참가 후기', '국내 유명 개발자 컨퍼런스에 참여하여 최신 기술 트렌드를 접하고 네트워킹을 하며 느낀 점을 공유합니다.\n\n![컨퍼런스 이미지](https://picsum.photos/seed/193/600/360)', '2021-02-24 08:10:00', '2021-02-24 08:10:00', NULL),
(194, 4, '피그마 단축키로 작업 속도 올리기', '마우스 이동을 줄이고 디자인 작업 효율을 극대화할 수 있는 피그마의 필수 단축키 10가지를 정리했습니다.\n\n![Figma 단축키 이미지](https://picsum.photos/seed/194/600/360)', '2021-02-19 16:00:00', '2021-02-19 16:00:00', NULL),
(195, 0, '파이썬 flask 프레임워크 기초', '가볍고 유연한 마이크로 프레임워크인 플라스크(Flask)를 사용하여 Hello World를 출력하는 간단한 웹 서버를 띄워봅니다.\n\n![Flask 이미지](https://picsum.photos/seed/195/600/360)', '2021-02-14 10:45:00', '2021-02-14 10:45:00', NULL),
(196, 2, '자바스크립트 배열 메서드: map, filter, reduce', '데이터를 변환하고 추출할 때 가장 많이 쓰이는 고차 함수 3대장 map, filter, reduce의 동작 원리와 예제입니다.\n\n![JS Array Methods 이미지](https://picsum.photos/seed/196/600/360)', '2021-02-09 14:20:00', '2021-02-09 14:20:00', NULL),
(197, 1, 'Git Ignore 파일 설정하기', 'node_modules나 API 키 파일 등 깃허브에 올리면 안 되는 파일들을 .gitignore 규칙에 추가하여 관리하는 법입니다.\n\n![Gitignore 이미지](https://picsum.photos/seed/197/600/360)', '2021-02-04 09:30:00', '2021-02-04 09:30:00', NULL),
(198, 3, 'API 문서 작성을 위한 Swagger(OpenAPI)', '코드 주석을 통해 자동으로 API 문서를 생성해주고 테스트 기능까지 제공하는 스웨거(Swagger) 도입기입니다.\n\n![Swagger 이미지](https://picsum.photos/seed/198/600/360)', '2021-01-30 15:10:00', '2021-01-30 15:10:00', NULL),
(199, 4, 'SPA(Single Page Application)의 장단점', '페이지 이동 없이 부드러운 사용자 경험을 제공하는 SPA의 구조적 특징과 SEO 문제 등 고려해야 할 단점들입니다.\n\n![SPA 이미지](https://picsum.photos/seed/199/600/360)', '2021-01-25 11:00:00', '2021-01-25 11:00:00', NULL),
(200, 0, '코딩 입문자를 위한 언어 추천', '2021년 기준, 목적(웹, 데이터, 앱 등)에 따라 입문자가 배우기 가장 좋은 프로그래밍 언어를 추천하고 이유를 설명합니다.\n\n![프로그래밍 언어 이미지](https://picsum.photos/seed/200/600/360)', '2021-01-20 08:30:00', '2021-01-20 08:30:00', NULL);
